function setBound(path,value){const parts=path.split('.');const scope=parts.shift();let obj=scope==='plate'?plate():scope==='draft'?wellDraft:exp();for(const k of parts.slice(0,-1))obj=obj[k];obj[parts.at(-1)]=value;if(parts.at(-1)==='seedingMedium')obj.medium=value}
function getBound(path){const parts=path.split('.');const scope=parts.shift();let obj=scope==='plate'?plate():scope==='draft'?wellDraft:exp();for(const k of parts)obj=obj[k];return obj||''}
document.addEventListener('click',async ev=>{const cmd=ev.target.closest('[data-command]');if(cmd){restoreRange();document.execCommand(cmd.dataset.command,false,null);exp().methodHtml=sanitize($('#methodEditor').innerHTML);changed();return}const b=ev.target.closest('[data-action]');if(!b||b.disabled)return;try{await handle(b.dataset.action,b)}catch(err){toast(err.message||t('操作未完成，请重试。','Operation failed. Please retry.'));console.error('Action failed:',b.dataset.action,err.name)}});
document.addEventListener('keydown',ev=>{if(ev.key==='Enter'&&ev.target.matches('.exp-card'))openExperiment(ev.target.dataset.id)});
document.addEventListener('input',ev=>{const el=ev.target;if(el.id==='fillMethodName'){fillState(exp()).name=el.value.slice(0,180);changed()}if(el.id==='fillReferenceText'){fillState(exp()).referenceText=el.value.slice(0,24000);changed()}if(el.dataset.fillField){editFill(exp(),el.dataset.fillField,el.value);changed();updateFillLine(el.dataset.fillField)}if(el.dataset.guide){setFact(exp(),el.dataset.guide,el.value);changed();updateGuideStatus(el.dataset.guide)}if(el.dataset.projectGuide){const info=ensureProjectInfo();info[el.dataset.projectGuide]=el.value.slice(0,18000);info.confirmed=false;const box=$('#guideProjectConfirmed');if(box)box.checked=false;changed()}if(el.dataset.bind){setBound(el.dataset.bind,el.value);changed();const id=writingIdForPath(el.dataset.bind);if(id){const button=el.closest('.field')?.querySelector('[data-action="polishField"]');if(button)button.disabled=!el.value.trim()}}if(el.dataset.well){pendingWell=true;wellDraft[el.dataset.well]=el.type==='checkbox'?el.checked:el.value;const check=document.querySelector(`[data-apply="${el.dataset.well}"]`);if(check)check.checked=true;draftFields.add(el.dataset.well)}if(el.dataset.stageApply){draftFields.add('steps');pendingWell=true;}if(el.dataset.step!==undefined&&el.value!=='__custom__'){pendingWell=true;const step=wellDraft.steps[Number(el.dataset.step)];step[el.dataset.key]=el.value;if(step.stage&&step.status!=='none'){step.status='used';const mode=document.querySelector('[data-stage-status="'+el.dataset.step+'"]');if(mode)mode.value='used';}markStepEdit(Number(el.dataset.step),el.dataset.key)}if(el.dataset.material)materialDraft[el.dataset.material]=el.value;if(el.dataset.attachment){const a=exp().results.attachments.find(a=>a.id===el.dataset.attachment);a.description=el.value;changed()}if(el.id==='search'){search=el.value;const start=el.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(start,start)}});
document.addEventListener('change',async ev=>{const el=ev.target;try{if(el.dataset.stageNone!==undefined){const i=Number(el.dataset.stageNone);wellDraft.steps[i].status=el.checked?'none':'used';markStepEdit(i,'status');renderEditorOnly();return;}if(el.dataset.stageCopy){if(el.checked)replaceStages.add(el.dataset.stageCopy);else replaceStages.delete(el.dataset.stageCopy);pendingWell=true;return;}if(el.dataset.stageStatus!==undefined){wellDraft.steps[Number(el.dataset.stageStatus)].status=el.value;draftFields.add('steps');pendingWell=true;renderEditorOnly();return;}if(el.dataset.step!==undefined&&el.dataset.key==='unit'&&el.value==='__custom__'){const step=wellDraft.steps[Number(el.dataset.step)],value=prompt(t('填写单位','Enter a unit'),step.unit||'');if(value!==null){step.unit=value.trim().slice(0,60);if(step.stage)step.status='used';markStepEdit(Number(el.dataset.step),'unit');}renderEditorOnly();return;}if(el.dataset.favoriteTarget){if(!el.value)return;const target=el.dataset.favoriteTarget,value=el.value;
if(target.startsWith('well:')){const key=target.slice(5);wellDraft[key]=value;draftFields.add(key);pendingWell=true;}
else if(target.startsWith('step:')){const i=Number(target.slice(5));wellDraft.steps[i].name=value;if(wellDraft.steps[i].stage)wellDraft.steps[i].status='used';markStepEdit(i,'name');}
else if(target==='method'){fillState(exp()).name=value;changed();}
else if(target.startsWith('fill:')){editFill(exp(),target.slice(5),value);changed();}
else{setBound(target,value);changed();}
render();return;}
if(el.dataset.fillLine){skipFillLine(exp(),el.dataset.fillLine,el.value);changed();render();return}if(el.id==='fillSavedTemplate'&&el.value){const x=state.methodTemplates.find(x=>x.id===el.value);if(x?.fill){loadFillTemplate(exp(),x,searchContext(exp(),state.materials));changed();render()}return}if(el.id==='fillReferenceFiles'){const f=fillState(exp()),files=[...el.files];if(f.images.length+files.length>2)throw Error(t('最多 2 张方法截图','Up to 2 method screenshots'));for(const file of files){if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>7*1024*1024)throw Error(t('截图请用小于 7 MB 的 PNG、JPEG 或 WebP','Use PNG, JPEG or WebP under 7 MB'));const stored=await fileToStored(file);f.images.push({id:stored.id,name:stored.name})}changed();render();return}if(el.dataset.guideConfirm){confirmFact(exp(),el.dataset.guideConfirm,el.checked);changed();updateGuideStatus(el.dataset.guideConfirm);return}if(el.id==='guideType'){const g=ensureGuide(exp());g.type=el.value;g.template=null;for(const f of Object.values(g.facts))f.confirmed=false;if(g.answers.length){g.answerHistory=[...(g.answerHistory||[]),...g.answers].slice(-100);g.answers=[];}changed();render();return}if(el.id==='guideTemplate'&&el.value){const template=(state.methodTemplates||[]).find(x=>x.id===el.value);if(template&&confirm(t('载入会替换问答内容，需重新确认。继续？','Loading replaces question answers and requires verification. Continue?'))){useTemplate(exp(),template);changed();render()}return}if(el.id==='guideProjectConfirmed'){ensureProjectInfo().confirmed=el.checked;changed();return}if(el.id==='guideJournal'){ensureProjectInfo().journal=el.value;changed();return}if(el.id==='reportOrientation'){await updateReportPrintPreview();return}if(['printScope','printOrientation','printConditions','printMaterials','printActual','printResults','printMethods','printHand'].includes(el.id)){await updatePrintPreview();return}if(el.dataset.apply){el.checked?draftFields.add(el.dataset.apply):draftFields.delete(el.dataset.apply)}if(el.dataset.bind&&['exp.methodMode','exp.methodLang','exp.methodFormat','exp.status'].includes(el.dataset.bind)){render()}if(el.id==='interfaceLanguage'){state.lang=el.value==='en'?'en':'zh';changed();render();return}if(el.id==='filter'){filter=el.value;render()}if(el.id==='multi')multi=el.checked;if(['fontName','fontSize','blockType'].includes(el.id)){restoreRange();if(el.id==='fontName')document.execCommand('fontName',false,el.value);if(el.id==='blockType')document.execCommand('formatBlock',false,el.value);if(el.id==='fontSize'){document.execCommand('fontSize',false,'7');for(const f of $('#methodEditor').querySelectorAll('font[size="7"]')){f.removeAttribute('size');f.style.fontSize=el.value+'pt'}}exp().methodHtml=sanitize($('#methodEditor').innerHTML);changed()}if(el.id==='materialPhotos'){const files=[...el.files];if(materialDraft.photos.length+files.length>8)throw Error(t('每份材料最多 8 张照片','Up to 8 photos per material'));for(const f of files){if(!['image/png','image/jpeg','image/webp','image/gif'].includes(f.type))throw Error('Use PNG, JPEG, WebP or GIF');const stored=await fileToStored(f);materialDraft.photos.push(stored.id)}renderMaterialModal()}if(el.id==='materialConfirmed'&&materialDraft)materialDraft.confirmed=el.checked;if(el.id==='resultFiles'){const files=[...el.files],e=exp();if(!files.length)return;const scope=prompt(t('附件关联范围（例如整个实验、Plate 01 / A1–A3）','Attachment scope (e.g. whole experiment, Plate 01 / A1–A3)'),t('整个实验','Whole experiment'));if(scope===null)return;for(const f of files){const a=await fileToStored(f);e.results.attachments.push({id:a.id,name:a.name,type:a.type,size:a.size,scope,description:''})}changed();render()}if(el.id==='importBackup'){const f=el.files[0];if(!f)return;const x=validateBackup(JSON.parse(await f.text()));if(!confirm(t('导入将替换当前全部数据。已导出当前备份并继续？','Import replaces all current data. Have you backed it up and want to continue?'))){el.value='';return}clearTimeout(saveTimer);await saveQueue.catch(()=>{});await restoreBackup(x);state=upgradeProtocolFields(x.state);state.trash=state.trash||[];dirty=false;activeId=null;view='experiments';render();toast(t('备份已恢复','Backup restored'))}if(el.id==='importCSV'){const f=el.files[0];if(!f)return;const rows=csvParse((await f.text()).replace(/^\uFEFF/,'')),headers=rows.shift().map(x=>x.trim().toLowerCase());if(!headers.includes('well'))throw Error('CSV needs a well column');const byPos=new Map();for(const r of rows){const item=Object.fromEntries(headers.map((h,i)=>[h,r[i]||''])),pos=item.well.trim().toUpperCase();if(!plate().wells[pos])throw Error('Unknown well: '+pos);if(!byPos.has(pos))byPos.set(pos,[]);byPos.get(pos).push(item)}if(!confirm(t(`将覆盖 ${byPos.size} 个孔的对应字段和处理步骤，继续？`,`Replace fields and steps in ${byPos.size} wells?`)))return;history();let i=0;const groupColors=new Map();for(const[pos,items]of byPos){const item=items[0],w=plate().wells[pos];if(!groupColors.has(item.group))groupColors.set(item.group,colors[i++%colors.length]);w.used=true;for(const k of ['group','cell','count','volume'])if(headers.includes(k))w[k]=item[k];if(headers.includes('parent_group'))w.parentGroup=item.parent_group;for(const[key,column]of [['seedingMedium','seeding_medium'],['assayMedium','assay_medium'],['collectionMethod','collection_method']])if(headers.includes(column))w[key]=item[column];if(headers.includes('seeding_medium'))w.medium=w.seedingMedium;w.color=groupColors.get(item.group);w.steps=items.filter(x=>x.treatment||x.concentration||x.duration||x.treatment_status==='none').map(x=>({...newStep(),name:x.treatment||'',status:['none','used'].includes(x.treatment_status)?x.treatment_status:undefined,stage:['pretreatment','stimulation'].includes(x.stage)?x.stage:'',concentration:x.concentration||'',unit:x.unit||'',duration:x.duration||''}))}changed();closeModal();selected.clear();wellDraft=null;render();toast(t('已导入 CSV，可撤销','CSV imported. Undo is available.'))}}catch(err){toast(err.message||t('操作失败','Operation failed'));console.error('Change failed:',el.id,err.name)}});
async function init(){try{await openDB();state=await loadState();if(!state){state=demoState();await saveState(state)}upgradeProtocolFields(state);state.lang=state.lang==='en'?'en':'zh';state.trash=state.trash||[];render()}catch(e){console.error('Initialization failed:',e.name,e.message);$('#app').innerHTML='<div class="empty"><h2>无法打开本地存储 / Storage unavailable</h2><p>请允许网站存储，或换用普通浏览器窗口。Please allow browser storage or use a regular browser window.</p></div>'}}
init();
async function generateWriting(ids,button,suggestTitle=false){if(aiBusy){toast(t('请等待当前 AI 请求完成。','Please wait for the current AI request.'));return}const e=exp(),fields=ids.filter(id=>writingFields[id]&&(suggestTitle||writingValue(e,id).trim())).map(id=>({id,text:writingValue(e,id)}));if(!fields.length){toast(t('请先填写需要整理的内容。','Enter some text first.'));return}const context=writingContext(e,fields.map(f=>f.id));if(suggestTitle&&!context.purpose.trim()&&!Object.values(context.experimentalDesign||{}).some(v=>Array.isArray(v)?v.length:String(v).trim())){toast(t('先填写实验目的，或添加细胞、分组、检测方法中的一项。','Add an aim, cell type, group or method first.'));return}const contextSignature=JSON.stringify(context),originalLabel=button.innerHTML;aiBusy=true;button.disabled=true;button.textContent=t('正在组织科研表达…','Rewriting scientific prose…');const requestLanguage=state.lang;try{const data=await api('polish',{fields,context,...(suggestTitle?{task:'suggest-title'}:{})});if(state.lang!==requestLanguage||activeId!==e.id||JSON.stringify(writingContext(e,fields.map(f=>f.id)))!==contextSignature){toast(t('页面或相关记录已变化，未修改原文。请重新生成。','The page or related records changed. Original text was not modified; generate again.'));return}const items=fields.map(field=>{const suggestion=data.suggestions?.find(x=>x.id===field.id);if(!suggestion||typeof suggestion.text!=='string'||!suggestion.text.trim())throw Error(t('建议稿不完整，请重试。','Incomplete suggestion. Please retry.'));return{id:field.id,original:field.text,proposed:suggestion.text,summary:suggestion.summary||'',notes:suggestion.notes||[],retainedDetails:suggestion.retainedDetails||[]}});writingSuggestion={experimentId:e.id,suggestTitle,items,fieldIds:fields.map(f=>f.id),contextSignature};showWritingSuggestion()}finally{aiBusy=false;if(button.isConnected){button.disabled=false;button.innerHTML=originalLabel}}}
function showWritingSuggestion(){showModal(writingSuggestion.suggestTitle?t('核对实验名称建议','Review suggested title'):t('核对科研英文重写','Review scientific rewriting'),`<p class="small">${t('原文尚未改变。可编辑建议稿，并勾选要采用的字段。','Your original text is unchanged. Edit the suggestions and select the fields you want to accept.')}</p>${writingSuggestion.items.map(item=>`<section class="writing-comparison"><label class="optionline"><input type="checkbox" data-accept-writing="${item.id}" checked><strong>${t(writingFields[item.id].zh,writingFields[item.id].en)}</strong></label><div class="grid2"><div><div class="comparison-caption">${t('当前原文','Original')}</div><div class="writing-original">${esc(item.original)}</div></div><label class="field"><span>${writingSuggestion.suggestTitle?t('建议名称（可修改）','Suggested title (editable)'):t('科研英文重写（可修改）','Scientific rewrite (editable)')}</span><textarea data-writing-proposal="${item.id}" rows="${['title','project'].includes(item.id)?3:6}">${esc(item.proposed)}</textarea></label></div>${writingEditorialNotes(item)}${item.notes.length?`<div class="notice warn small"><strong>${t('需要核对的科学含义','Scientific points to confirm')}</strong><ul>${item.notes.map(note=>`<li>${esc(note)}</li>`).join('')}</ul></div>`:''}</section>`).join('')}`,btn(t('不采用','Keep original'),'close')+btn(writingSuggestion.suggestTitle?t('采用此名称','Use this title'):t('采用所选英文','Accept selected English'),'acceptWriting','primary'))}
function showWritingHistory(){const history=exp().aiWritingHistory||[];showModal(t('文字修改记录','Writing revision history'),history.map(item=>`<section class="writing-comparison"><div class="cardhead"><strong>${writingFields[item.field]?t(writingFields[item.field].zh,writingFields[item.field].en):esc(item.field)}</strong><span class="small">${new Date(item.date).toLocaleString()}</span>${btn(t('恢复原文','Restore original'),'restoreWriting','',`data-id="${item.id}"`)}</div><div class="grid2"><div><div class="comparison-caption">${t('原文','Original')}</div><div class="writing-original">${esc(item.original)}</div></div><div><div class="comparison-caption">${t('已采用文字','Accepted text')}</div><div class="writing-original">${esc(item.accepted)}</div></div></div>${writingEditorialNotes(item)}</section>`).join('')||`<div class="empty">${t('采用建议后，会在这里保留原文。','Originals will appear here after you accept suggestions.')}</div>`)}
function methodResultHtml(result){return (result.heading?'<h3>'+esc(result.heading)+'</h3>':'')+(result.paragraphs||[]).map(p=>'<p>'+esc(p).replace(/\n/g,'<br>')+'</p>').join('')}

function ensureProjectInfo(){state.methodProjects??={};const key=projectKey(exp());return state.methodProjects[key]??=(clone(projectInfo(state,exp())));}
function updateFillLine(fieldId){
 const f=fillState(exp()),field=f.fields.find(x=>x.id===fieldId),origin=document.querySelector('[data-fill-origin="'+fieldId+'"]');
 if(origin)origin.textContent=t('填本次条件','Your condition');
 for(const line of f.lines.filter(l=>l.parts.some(p=>p.field===fieldId))){const label=document.querySelector('[data-fill-line-state="'+line.id+'"]');if(label)label.textContent=lineComplete(f,line)?t('已填完整，生成时统一确认','Complete; confirm when drafting'):t('还有空白，可以稍后补','Some blanks remain; add later');}
}
function fillRequestSnapshot(e){const f=fillState(e);return JSON.stringify({language:state.lang,name:f.name,referenceText:f.referenceText,images:f.images,context:searchContext(e,state.materials)});}
async function findFillTemplate(button,mode){
 if(aiBusy)return;const e=exp(),f=fillState(e),name=f.name.trim();
 if(!name){toast(t('先输入方法名称，例如 Western blot','Enter a method name, e.g. Western blot'));$('#fillMethodName')?.focus();return;}
 if(mode==='reference'&&!f.referenceText.trim()&&!f.images.length){toast(t('请粘贴方法文字或上传截图','Paste method text or upload a screenshot'));return;}
 const snapshot=fillRequestSnapshot(e),label=button.innerHTML;aiBusy=true;button.disabled=true;button.textContent=mode==='search'?t('正在找参考并拆成填空…','Finding references and creating blanks…'):t('正在读取范例…','Reading your reference…');delete f.error;delete f.failedSearch;
 try{
  const images=mode==='reference'?await Promise.all(f.images.map(async image=>{const file=await getFile(image.id);if(!file)throw Error(t('截图文件未找到，请重新上传','Reference image missing. Upload it again.'));return file.data;})):[];
  const result=await api('method-template',{name,mode,context:(()=>{const c=searchContext(e,state.materials);return{cell:c.cell,plateSize:c.plateSize,materials:c.materials.map(m=>({name:m.name}))}})(),referenceText:mode==='reference'?f.referenceText:'',images,excludeUrls:button.dataset.alternative?f.sources.map(s=>s.url).filter(Boolean):[]});
  if(activeId!==e.id||fillRequestSnapshot(e)!==snapshot){toast(t('记录已变化，未替换填空内容。请重新搜索。','The record changed. No blanks were replaced; search again.'));return;}
  applyFillTemplate(e,{...result,language:state.lang},searchContext(e,state.materials),mode);changed();aiBusy=false;render();toast(t('模板已准备好，只填本次条件即可','Template ready. Fill in your actual conditions.'));
 }catch(err){f.error=err.message;f.failedSearch={name,date:new Date().toISOString(),sources:err.details?.sources||[],searchCompleted:!!err.details?.searchCompleted};changed();aiBusy=false;if(activeId===e.id)render();throw err;}
 finally{aiBusy=false;if(button.isConnected){button.disabled=false;button.innerHTML=label;}}
}
async function generateFilledMethods(button){
 if(aiBusy)return;const e=exp(),f=fillState(e);
 if(!f.lines.length){toast(t('请先输入方法名，让 AI 生成填空模板。','Enter a method name and create the fill-in template first.'));$('#fillMethodName')?.focus();return;}
 if(f.templateName&&f.templateName.trim().toLowerCase()!==f.name.trim().toLowerCase()){toast(t('方法名称已改变，请重新搜索生成对应填空。','Method name changed. Search again to create the matching blanks.'));return;}
 const facts=confirmFilledLines(e);changed();
 if(!facts.sentences.length){toast(t('至少填完整一句；不清楚的内容可以留空。','Complete at least one sentence; unknown details can stay blank.'));return;}
 const payload=guidePayload(e,state.materials,state),signature=sourceSignature(payload),previous=e.methodHtml,label=button.innerHTML;
 const reference=f.sources.map(s=>s.title+(s.url?' · '+s.url:'')).join('\n');aiBusy=true;button.disabled=true;button.textContent=t('正在整理英文段落…','Drafting Methods…');
 try{
  const result=await api('methods',{record:payload,reference});
  if(activeId!==e.id||sourceSignature(guidePayload(e,state.materials,state))!==signature){toast(t('条件已变化，未替换正文。请重新生成。','Conditions changed. No prose was replaced. Generate again.'));return;}
  const missing=facts.missing.map(l=>l.label+(l.blanks.length?'：'+l.blanks.join('、'):t('：尚未确认',': not confirmed')));
  result.missing=[...new Set([...(result.missing||[]),...missing])];methodSuggestion={experimentId:e.id,source:clone(payload),signature,reference,result,previous};showMethodSuggestion();
 }finally{aiBusy=false;if(button.isConnected){button.disabled=false;button.innerHTML=label;}}
}
function updateGuideStatus(key){const f=ensureGuide(exp()).facts[key],card=$('#guide-'+key);if(!card)return;const check=card.querySelector('[data-guide-confirm]'),label=card.querySelector('[data-guide-status]');check.checked=f.confirmed;check.disabled=!f.text?.trim();label.textContent=f.confirmed?t('已确认','Confirmed'):f.text?t('待确认','Review'):t('可用关键词','Keywords welcome');label.classList.toggle('confirmed',f.confirmed);}
function hasGuideContent(record){return record.plates.some(p=>p.wells.length)||record.supplementalProcedure?.trim()||record.guide.facts.length||record.guide.fill?.sentences?.length||record.guide.answers.length||record.guide.shared?.culture?.trim();}
async function checkGuide(button){
 if(aiBusy)return;
 const e=exp(),record=guidePayload(e,state.materials,state);
 if(!hasGuideContent(record)){toast(t('请先填写关键条件并勾选确认，或添加孔板记录。','Add and confirm key conditions, or record a plate first.'));return;}
 const signature=sourceSignature(record),label=button.innerHTML,previous=e.methodHtml;aiBusy=true;button.disabled=true;button.textContent=t('检查关键缺口…','Checking key gaps…');
 try{const result=await api('method-check',{record});if(activeId!==e.id||sourceSignature(guidePayload(e,state.materials,state))!==signature){toast(t('实验条件已变化，请重新检查。','The record changed. Check again.'));return;}guideCheck={experimentId:e.id,record,signature,previous,questions:(result.questions||[]).filter(q=>typeof q.question==='string'&&!ensureGuide(e).answers.some(a=>a.confirmed&&a.question.trim().toLowerCase()===q.question.trim().toLowerCase())).slice(0,5),warnings:result.warnings||[]};showGuideCheck();}
 finally{aiBusy=false;if(button.isConnected){button.disabled=false;button.innerHTML=label;}}
}
function showGuideCheck(){
 const c=guideCheck,pending=pendingFacts(exp()),qs=c.questions;
 showModal(t('只补充关键缺口','Add only the key details'),'<p class="small">'+t('可用中文或关键词回答。没有记录的条件请留空，AI 不会猜测。','Answer in Chinese, English or keywords. Leave unknown conditions blank; AI will not guess.')+'</p>'+(pending.length?'<div class="notice warn">'+t('有 '+pending.length+' 项回答尚未勾选确认，未用于本次检查。可返回确认，或先生成草稿。',pending.length+' answers are unconfirmed and excluded. Return to verify them, or draft without them.')+'</div>':'')+(c.record.mode==='planned_protocol'?'<div class="notice warn">'+t('依据为实验计划：生成的过去时正文只是预拟稿，尚未确认执行。','Source: experiment plan. Past-tense prose is an unverified manuscript draft.')+'</div>':'')+(qs.length?qs.map((q,i)=>'<label class="field guide-followup"><span><b>'+String(i+1).padStart(2,'0')+' · '+esc(q.question)+'</b> <span class="guide-status">'+(q.priority==='critical'?t('关键','Key'):t('可后补','Later'))+'</span></span>'+(q.reason?'<small>'+esc(q.reason)+'</small>':'')+'<textarea rows="2" data-guide-reply="'+i+'" placeholder="'+t('不知道可以留空','Leave blank if unknown')+'"></textarea></label>').join(''):'<div class="notice">'+t('此次检查没有提出新的关键问题。仍需核对生成稿的每一个条件。','No additional key questions were raised. Verify every condition in the draft.')+'</div>')+(c.warnings.length?'<ul class="small">'+c.warnings.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':'')+'<p class="small">'+t('点击“确认回答并生成”即确认本次填写的补充内容；留空的问题会保留为草稿缺口。','Confirming verifies the follow-up answers for this draft. Unanswered questions remain unresolved.')+'</p>',btn(t('返回填写','Back'),'close')+btn(t('先生成不完整草稿','Draft with current facts'),'guideDraft')+btn(qs.length?t('确认回答并生成','Confirm answers & draft'):t('生成方法段落','Draft Methods'),'guideAnswers','primary'));
}
async function draftGuide(button,withAnswers){
 if(aiBusy)return;const c=guideCheck,e=exp();
 if(!c||c.experimentId!==e.id||sourceSignature(guidePayload(e,state.materials,state))!==c.signature)throw Error(t('条件已变化，请重新检查。','Conditions changed. Check again.'));
 const replies=withAnswers?c.questions.map((_,i)=>document.querySelector('[data-guide-reply="'+i+'"]')?.value||''):[];
 if(withAnswers){recordAnswers(e,c.questions,replies);changed();}
 const payload=guidePayload(e,state.materials,state),signature=sourceSignature(payload),reference=e.methodReference??METHODS_REFERENCE,label=button.innerHTML;const reviewQuestions=c.questions.filter((_,i)=>!replies[i]?.trim()).map(q=>q.question);
 c.signature=signature;c.record=payload;aiBusy=true;for(const b of $('#modal').querySelectorAll('.modal-foot button'))b.disabled=true;button.textContent=t('正在组织科研段落…','Drafting scientific prose…');
 try{const result=await api('methods',{record:payload,reference});if(activeId!==e.id||sourceSignature(guidePayload(e,state.materials,state))!==signature){toast(t('条件已改变，未替换任何正文。','Conditions changed. No manuscript text was replaced.'));return;}result.missing=[...new Set([...(result.missing||[]),...reviewQuestions])];result.warnings=[...new Set([...(result.warnings||[]),...c.warnings])];methodSuggestion={experimentId:e.id,source:clone(payload),signature,reference,result,previous:c.previous};showMethodSuggestion();}
 finally{aiBusy=false;if(button.isConnected)button.innerHTML=label;for(const b of $('#modal').querySelectorAll('.modal-foot button'))b.disabled=false;}
}
function showMethodSuggestion(){const s=methodSuggestion;showModal(t('核对论文 Methods 建议稿','Review manuscript Methods draft'),`${s.source.mode==='planned_protocol'?`<div class="notice warn">${t('这是基于计划的论文方法草稿，过去时仅用于稿件写作；不代表实验已完成。请核对实际执行后再投稿。','This manuscript-style draft is based on a plan. Past tense is editorial wording, not confirmation that the experiment was performed. Verify actual execution before publication.')}</div>`:''}<div class="method-proposal">${methodResultHtml(s.result)}</div>${methodReviewDetails(s.result,s.source)}${s.result.missing?.length?`<div class="notice warn"><strong>${t('需要补充的信息','Information to add')}</strong><ul>${s.result.missing.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}${s.result.warnings?.length?`<div class="notice"><strong>${t('需要核对','Review')}</strong><ul>${s.result.warnings.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}<p class="small">${t('只有点击采用才替换编辑区。原稿保留在历史草稿中；上述核对提示不会混入正文。','The editor changes only when you accept. Existing text is preserved in draft history, and review notes stay outside the manuscript text.')}</p>`,btn(t('不采用','Keep current draft'),'close')+btn(t('采用方法草稿','Accept method draft'),'acceptMethods','primary'))}

function reviewCopyStatus(){const e=exp();if(e.methodSource&&sourceSignature(e.methodSource)!==sourceSignature(guidePayload(e,state.materials,state))&&!confirm(t('方法生成后，实验记录已改变。仍复制旧草稿？','The record changed after drafting. Copy the previous draft?')))return false;const plan=e.methodSource?.mode==='planned_protocol',incomplete=e.methodReview?.missing?.length||e.methodReview?.warnings?.length;if(!plan&&!incomplete)return true;return confirm(t(plan?'此稿依据实验计划，尚未确认执行。仍复制草稿？':'此稿仍有待核对信息。仍复制草稿？',plan?'This draft is based on an unverified plan. Copy the draft?':'This draft has unresolved review points. Copy the draft?'));}
function methodReviewDetails(result,source){const labels={samples:t('样本与分组','Samples and groups'),preparation:t('准备条件','Preparation'),treatment:t('处理条件','Treatments'),measurement:t('检测条件','Measurement'),analysis:t('数据处理','Analysis'),repeats:t('独立重复','Replicates'),plates:t('孔板记录','Plate record'),materials:t('已确认材料','Verified materials'),supplementalProcedure:t('补充流程','Additional procedure'),actualNotes:t('实际操作记录','Execution notes'),'shared.culture':t('共用培养记录','Shared culture'),'shared.statistics':t('共用统计记录','Shared statistics'),'shared.ethics':t('共用伦理记录','Shared ethics'),'shared.data':t('共用数据资料','Shared data')};if(!result.summary&&!result.trace?.length)return'';return '<details class="guide-optional guide-trace"><summary>'+t('中文核对与段落来源','Review summary and paragraph sources')+'</summary>'+(result.summary?'<p>'+esc(result.summary)+'</p>':'')+(result.trace||[]).map(item=>'<p><strong>'+t('段落 ','Paragraph ')+(item.paragraph+1)+'</strong> · '+item.sources.map(id=>esc(labels[id]||source?.guide?.fill?.sentences?.find(l=>'fill.'+l.id===id)?.text||source?.guide?.answers?.find(a=>a.id===id)?.question||id)).join(' / ')+'</p>').join('')+'<p class="small">'+t('来源映射由 AI 提供，仅辅助人工核对；完整记录可在“查看生成依据”中检查。','AI source mapping is a review aid. Inspect the full record using Inspect source.')+'</p></details>';}

function writingEditorialNotes(item){return(item.summary?'<p class="small writing-edit-summary"><strong>'+t('本次重写：','Editorial change: ')+'</strong>'+esc(item.summary)+'</p>':'')+(item.retainedDetails?.length?'<details class="notice small"><summary>'+t('未写入本字段的原始细节（仍保留在原文）','Original details kept outside this field')+'</summary><ul>'+item.retainedDetails.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul></details>':'');}

function favoriteTabs(){return '<div class="favorite-tabs">'+Object.entries(favoriteKinds).map(([k,d])=>btn(t(d.zh,d.en),'favoriteTab',k===favoriteKind?'soft':'quiet',`data-kind="${k}"`)).join('')+'</div>';}
function favoriteCards(){const entries=savedFavorites(state,favoriteKind),archived=savedFavorites(state,favoriteKind,true);return '<div data-favorites-panel>'+favoriteTabs()+'<div class="cardhead"><p class="small">'+t('★ 你保存的内容可跨实验复用。选择时复制到当前记录，之后可自由修改。','★ Saved entries are reusable across experiments. Selecting copies the text into your record; you can then edit it.')+'</p>'+btn('＋ '+t('新增','Add entry'),'favoriteNew','primary',`data-kind="${favoriteKind}"`)+'</div><div class="favorite-cards">'+entries.map(x=>'<article class="favorite-card"><h3>'+esc(x.name)+'</h3><p>'+esc(x.value)+'</p><div class="actions">'+btn(t('编辑','Edit'),'favoriteEdit','quiet',`data-id="${esc(x.id)}"`)+btn(t('归档','Archive'),'favoriteArchive','quiet',`data-id="${esc(x.id)}"`)+'</div></article>').join('')+'</div>'+(!entries.length?'<p class="empty">'+t('还没有保存的条目。把完整培养基配方、常用细胞或处理名称保存一次，以后直接选。','No saved entries yet. Save a full medium recipe, cell or treatment name once, then reuse it.')+'</p>':'')+'<details class="guide-optional"><summary>'+t('已有记录与常见名称','Existing records & common names')+'</summary><p class="small">'+t('这里只提供名称快捷选项，不代表已核对完整配方或实验条件。浓度、时间和厂家按本次实验填写。','These are name shortcuts, not verified recipes or experimental conditions. Record your actual doses, times and manufacturers.')+'</p><div class="actions">'+favoriteChoices(state,favoriteKind).filter(x=>x.source!=='saved').map(x=>btn(esc(x.label),'favoriteNew','',`data-kind="${favoriteKind}" data-value="${esc(x.value)}"`)).join('')+'</div></details>'+(archived.length?'<details class="guide-optional"><summary>'+t('已归档','Archived')+' ('+archived.length+')</summary>'+archived.map(x=>'<div class="cardhead"><span>'+esc(x.name)+'</span>'+btn(t('恢复','Restore'),'favoriteRestore','quiet',`data-id="${esc(x.id)}"`)+'</div>').join('')+'</details>':'')+'</div>';}
function favoritesPage(){return '<div class="eyebrow">LESS TYPING. MORE SCIENCE.</div><div class="pagehead"><div><h1>'+t('常用内容，只写一次。','Write it once. Reuse it.')+'</h1><p class="sub">'+t('培养基、细胞、分组、处理、检测和项目，在实验里直接选择。随完整备份一起保存。','Media, cells, groups, treatments, readouts, methods and projects. Available in your experiments and included in full backups.')+'</p></div></div><section class="card">'+favoriteCards()+'</section>';}
function showFavoritesModal(){showModal(t('常用库','Reusable lists'),favoriteCards(),btn(t('完成','Done'),'favoriteClose','primary'));}
function favoriteForm(kind,id=null,value=''){favoriteKind=Object.hasOwn(favoriteKinds,kind)?kind:'medium';favoriteEditingId=id;const item=id?state.favorites?.find(x=>x.id===id):null;showModal(t('保存常用内容','Save reusable entry'),'<div data-favorites-panel><p class="small">'+t(favoriteKinds[favoriteKind].zh,favoriteKinds[favoriteKind].en)+'</p><label class="field"><span>'+t('列表中显示的名称','Name shown in the list')+'</span><input id="favoriteName" maxlength="160" value="'+esc(item?.name||value.slice(0,160))+'" placeholder="'+t('例如：HEK293T complete medium','e.g. HEK293T complete medium')+'"></label><label class="field"><span>'+t('选择时填入的文字 / 完整配方（可选）','Text to insert / full recipe (optional)')+'</span><textarea id="favoriteValue" rows="4" maxlength="6000" placeholder="'+t('留空则填入上面的名称。培养基可写基础培养基、补充物、浓度及厂家。','Leave blank to insert the name. For media, record the base medium, supplements, concentrations and manufacturers.')+'">'+esc(item?.value||value)+'</textarea></label><p class="small">'+t('只保存你填写的内容，不自动补充浓度或成分。修改常用库不会回写旧实验。','Only your entered text is saved; no concentrations or ingredients are assumed. Editing a saved entry does not rewrite previous experiments.')+'</p></div>',btn(t('返回','Back'),'favoriteBack')+btn(t('保存到常用库','Save entry'),'favoriteSave','primary'));$('#favoriteName').focus();}

function currentFavoriteText(target){if(target.startsWith('well:'))return wellDraft?.[target.slice(5)]||'';if(target.startsWith('step:'))return wellDraft?.steps?.[Number(target.slice(5))]?.name||'';if(target==='method')return fillState(exp()).name;if(target.startsWith('fill:'))return fillState(exp()).fields.find(x=>x.id===target.slice(5))?.value||'';return getBound(target);}
function protocolStages(w){return '<section class="protocol-stages">'+['pretreatment','stimulation'].map(stage=>'<section class="protocol-stage"><div class="cardhead"><h3>'+t(stage==='pretreatment'?'预处理':'刺激',stage==='pretreatment'?'Pretreatment':'Stimulation')+'</h3>'+btn('＋','addProtocolStep','quiet',`data-stage="${stage}" title="${t('增加一项','Add another')}"`)+'</div>'+w.steps.map((s,i)=>{
 if(s.stage!==stage)return'';const label=stage==='pretreatment'?'Pretreatment':'Stimulation',none=s.status==='none',options=[...protocolUnits,...(s.unit&&!protocolUnits.includes(s.unit)?[s.unit]:[])];
 const duration='<label class="field"><span>'+t(none?'等待时间（可选）':'时长',none?'Waiting time (optional)':'Duration')+'</span><input aria-label="'+label+' duration" data-step="'+i+'" data-key="duration" value="'+esc(s.duration||'')+'" placeholder="1 h / 15 min"></label>';
 return '<div class="protocol-entry"><label class="optionline"><input type="checkbox" data-stage-none="'+i+'" aria-label="'+(stage==='pretreatment'?'No pretreatment':'No stimulation')+'" '+(none?'checked':'')+'>'+t(stage==='pretreatment'?'无预处理':'无刺激',stage==='pretreatment'?'No pretreatment':'No stimulation')+'</label>'+(!none?'<label class="field"><span>'+t('名称（输入或选常用）','Name (type or choose saved)')+'</span><input aria-label="'+label+' name" list="stage-names-'+i+'" data-step="'+i+'" data-key="name" value="'+esc(s.name||'')+'" placeholder="'+t('输入或选择…','Type or choose…')+'"><datalist id="stage-names-'+i+'">'+favoriteChoices(state,'treatment').map(x=>'<option value="'+esc(x.value)+'" label="'+esc(x.label)+'"></option>').join('')+'</datalist></label><div class="protocol-values"><label class="field"><span>'+t('终浓度','Final dose')+'</span><input aria-label="'+label+' concentration" data-step="'+i+'" data-key="concentration" value="'+esc(s.concentration||'')+'"></label><label class="field"><span>'+t('单位','Unit')+'</span><select aria-label="'+label+' unit" data-step="'+i+'" data-key="unit">'+options.map(v=>'<option value="'+esc(v)+'" '+(v===(s.unit||'')?'selected':'')+'>'+esc(v||t('选择','Select'))+'</option>').join('')+'<option value="__custom__">'+t('其他…','Other…')+'</option></select></label>'+duration+'</div>':duration)+'<details class="protocol-extra"><summary>'+t('更多 / 保存常用','More / save reusable')+'</summary>'+(!none?favoritePicker(state,'treatment','step:'+i,s.name,{esc,t,btn})+stageExtraInputs(s,i):'')+btn(t('移除此项','Remove entry'),'removeStep','quiet danger',`data-index="${i}"`)+'</details></div>';
 }).join('')+(selected.size>1?'<label class="checklabel stage-copy"><input type="checkbox" data-stage-copy="'+stage+'" '+(replaceStages.has(stage)?'checked':'')+'>'+t('用本区完整条件覆盖所选孔','Copy this whole stage to selected wells')+'</label>':'')+'</section>').join('')+'</section>';}

function stageExtraInputs(s,i){const materials=exp().materialIds.map(id=>materialFor(exp(),state.materials,id)).filter(Boolean);return '<label class="field"><span>'+t('关联材料','Linked material')+'</span><select data-step="'+i+'" data-key="materialId"><option value="">'+t('暂不关联','Not linked')+'</option>'+materials.map(m=>'<option value="'+esc(m.id)+'" '+(s.materialId===m.id?'selected':'')+'>'+esc(m.name)+'</option>').join('')+'</select></label><label class="field"><span>'+t('材料名称（未关联时）','Material name (if unlinked)')+'</span><input data-step="'+i+'" data-key="materialName" value="'+esc(s.materialName||'')+'"></label><label class="field"><span>'+t('温度','Temperature')+'</span><input data-step="'+i+'" data-key="temperature" value="'+esc(s.temperature||'')+'"></label><div class="grid2"><label class="field"><span>'+t('加入体积','Added volume')+'</span><input data-step="'+i+'" data-key="volume" value="'+esc(s.volume||'')+'"></label><label class="field"><span>'+t('总体积','Total volume')+'</span><input data-step="'+i+'" data-key="totalVolume" value="'+esc(s.totalVolume||'')+'"></label></div><label class="field"><span>'+t('操作描述','Description')+'</span><textarea data-step="'+i+'" data-key="description">'+esc(s.description||'')+'</textarea></label>';}

function captureEditorView(){const a=document.activeElement;return {x:window.scrollX,y:window.scrollY,editor:$('.editor-body')?.scrollTop||0,editorMax:$('.well-editor')?.style.maxHeight||'',focus:a?.id?{id:a.id}:a?.dataset.step!==undefined?{step:a.dataset.step,key:a.dataset.key}:a?.dataset.stageNone!==undefined?{none:a.dataset.stageNone}:a?.dataset.well?{well:a.dataset.well}:null};}
function restoreEditorView(saved){const editor=$('.well-editor');if(editor&&saved.editorMax)editor.style.maxHeight=saved.editorMax;const body=$('.editor-body');if(body)body.scrollTop=saved.editor;let f;if(saved.focus?.id)f=document.getElementById(saved.focus.id);else if(saved.focus?.step!==undefined)f=document.querySelector('[data-step="'+saved.focus.step+'"][data-key="'+saved.focus.key+'"]');else if(saved.focus?.none!==undefined)f=document.querySelector('[data-stage-none="'+saved.focus.none+'"]');else if(saved.focus?.well)f=document.querySelector('[data-well="'+saved.focus.well+'"]');f?.focus({preventScroll:true});window.scrollTo(saved.x,saved.y);}
function render(){const key=[view,activeId,tab,plateId].join(':'),saved=render.key===key?captureEditorView():null;renderContent();render.key=[view,activeId,tab,plateId].join(':');if(saved)restoreEditorView(saved);else fitWellEditor();}
function markStepEdit(index,key,replace=false){const s=wellDraft.steps[index];if(!s?.stage){draftFields.add('steps');const c=document.querySelector('[data-apply="steps"]');if(c)c.checked=true;}else{const ordinal=wellDraft.steps.slice(0,index).filter(x=>x.stage===s.stage).length;stageEdits[s.stage]??={};stageEdits[s.stage][ordinal]??=new Set();stageEdits[s.stage][ordinal].add(key);if(key!=='duration')stageEdits[s.stage][ordinal].add('status');if(replace)replaceStages.add(s.stage);}pendingWell=true;}

function fitWellEditor(){const editor=$('.well-editor');if(!editor||!$('.editor-footer'))return;const top=Math.max(16,editor.getBoundingClientRect().top),height=Math.max(240,window.innerHeight-top-16);editor.style.maxHeight=height+'px';}
window.addEventListener('resize',fitWellEditor);window.addEventListener('scroll',fitWellEditor,{passive:true});

function experimentReport(){const e=exp();return reportHtml(e,state.materials,{t,sanitize,methodStale:!!e.methodSource&&sourceSignature(e.methodSource)!==sourceSignature(guidePayload(e,state.materials,state))});}
